    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// SCHÉMA BASE DE DONNÉES\n// Modèle Prisma Complet\n// ÉNUMÉRATIONS\n\nenum UserRole {\n  SUPER_ADMIN\n  ADMIN\n  USER\n}\n\nenum AppointmentStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n}\n\n// UTILISATEURS\n\nmodel User {\n  id        String    @id @default(cuid())\n  email     String    @unique\n  password  String // Hash bcrypt\n  firstName String\n  lastName  String\n  phone     String?\n  avatar    String? // URL vers image Cloudinary\n  role      UserRole  @default(USER)\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime? // Soft delete\n\n  // Relations\n  rendezVous RendezVous[]\n  avis       Avis[]\n  likes      Like[]\n\n  @@index([email])\n  @@index([role])\n}\n\n// PRODUITS ET CATÉGORIES\n\nmodel Categorie {\n  id          String   @id @default(cuid())\n  nom         String   @unique\n  description String?\n  icone       String?\n  ordre       Int      @default(0)\n  createdAt   DateTime @default(now())\n\n  produits Produit[]\n\n  @@index([nom])\n}\n\nmodel Produit {\n  id           String   @id @default(cuid())\n  nom          String\n  description  String\n  prix         Float\n  stock        Int\n  categorie_id String\n  images       String[] // URLs Cloudinary\n  sku          String?  @unique\n  publie       Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  // Relations\n  categorie Categorie @relation(fields: [categorie_id], references: [id])\n  avis      Avis[]\n  likes     Like[]\n\n  @@index([categorie_id])\n  @@index([publie])\n}\n\n// AVIS ET ÉVALUATIONS\n\nmodel Avis {\n  id             String   @id @default(cuid())\n  note           Int // 1-5\n  titre          String\n  contenu        String\n  produit_id     String\n  utilisateur_id String\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // Relations\n  produit     Produit @relation(fields: [produit_id], references: [id], onDelete: Cascade)\n  utilisateur User    @relation(fields: [utilisateur_id], references: [id], onDelete: Cascade)\n\n  // Contraintes\n  @@unique([utilisateur_id, produit_id]) // Un avis par utilisateur par produit\n  @@index([produit_id])\n  @@index([utilisateur_id])\n}\n\n// LIKES\nmodel Like {\n  id             String   @id @default(cuid())\n  utilisateur_id String\n  produit_id     String\n  createdAt      DateTime @default(now())\n\n  // Relations\n  utilisateur User    @relation(fields: [utilisateur_id], references: [id], onDelete: Cascade)\n  produit     Produit @relation(fields: [produit_id], references: [id], onDelete: Cascade)\n\n  // Contraintes\n  @@unique([utilisateur_id, produit_id])\n  @@index([produit_id])\n}\n\n// RENDEZ-VOUS\nmodel TypeSeance {\n  id          String   @id @default(cuid())\n  nom         String   @unique\n  description String\n  durees      Int[] // [30, 60, 90]\n  prix        Float\n  createdAt   DateTime @default(now())\n\n  rendezVous RendezVous[]\n}\n\nmodel RendezVous {\n  id             String            @id @default(cuid())\n  utilisateur_id String\n  date_heure     DateTime\n  duree          Int // minutes\n  type_seance_id String\n  notes          String?\n  statut         AppointmentStatus @default(PENDING)\n  raison_refus   String?\n  createdAt      DateTime          @default(now())\n  updatedAt      DateTime          @updatedAt\n\n  // Relations\n  utilisateur User       @relation(fields: [utilisateur_id], references: [id], onDelete: Cascade)\n  type_seance TypeSeance @relation(fields: [type_seance_id], references: [id])\n\n  @@index([utilisateur_id])\n  @@index([date_heure])\n  @@index([statut])\n}\n\n// CONFIGURATION\nmodel Configuration {\n  id          String   @id @default(cuid())\n  cle         String   @unique\n  valeur      String // JSON stringifié\n  description String?\n  updatedAt   DateTime @updatedAt\n}\n",
